const textContent = await page.getTextContent();

console.log('==> TEXT_CONTENT', textContent);

// Extract font sizes from transform[3] before TextLayer renders
// (transform[3] = scaleY = font size in PDF points at 72 DPI)
const fontSizesFromTransform = textContent.items.map((item) => {
	if ('transform' in item && Array.isArray(item.transform)) {
		return Math.abs(item.transform[3]) * viewport.scale * PDF_TO_CSS_UNITS;
	}
	return 12 * viewport.scale * PDF_TO_CSS_UNITS; // fallback: 12pt default
});

const textLayer = new pdfjs.TextLayer({
	textContentSource: textContent,
	container: textLayerDiv,
	viewport: viewport
});
await textLayer.render();
pageWrapper.appendChild(textLayerDiv);

// Use querySelectorAll to get actual text spans — excludes markedContent
// wrapper divs, giving guaranteed 1:1 alignment with text content strings.
const textSpans = Array.from(
	textLayerDiv.querySelectorAll<HTMLElement>('span:not(.markedContent)')
);

// Filter fontSizes to match textSpans (excluding empty/whitespace-only items)
// textContent.items may include items that don't render as spans
const fontSizes: number[] = [];
let spanIdx = 0;
for (let i = 0; i < textContent.items.length && spanIdx < textSpans.length; i++) {
	const item = textContent.items[i];
	if ('str' in item && item.str.trim()) {
		fontSizes.push(fontSizesFromTransform[i]);
		spanIdx++;
	}
}
// Fill remaining if there's a mismatch (fallback)
while (fontSizes.length < textSpans.length) {
	fontSizes.push(12 * viewport.scale * PDF_TO_CSS_UNITS);
}

pagesData.push({
	pageWrapper,
	viewport: { width: viewport.width, height: viewport.height, scale: viewport.scale },
	textDivs: textSpans,
	textContentItemsStr: textSpans.map((s) => s.textContent ?? ''),
	fontSizes
});

